-- failure incidents that motivated this). This script is kept for repo
-- history / fresh-environment replay and is safe to run more than once.

UPDATE public.service_pricing
SET description_en = COALESCE(description_en, '') || E'\n\n' || 'General process: lodge the updated particulars (e.g. residential address, nationality, ID details) with ACRA via BizFile+, typically within 14 days of the change taking place. No board/shareholder resolution is normally required for a routine particulars update— the change is administrative and does not need a special filing fee (a system where Tassure is the appointed secretary handles this as part of the annual secretarial retainer).',
    description_cn = COALESCE(description_cn, '') || E'\n\n' || '一般流程：将更新后的资料（如住址、国籍、身份证明信息等）通过BizFile+向ACRA申报，一般须在变更发生后14天内完成。常规资料更新通常不需要董事会/股东决议，属于行政性变更，一般无需另外的申报费用（若Tassure是委任秘书，这类更新已包含在年度秘书服务中）。',
    remarks_en = CASE WHEN remarks_en IS NULL OR remarks_en = '' THEN 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' ELSE remarks_en || ' ' || 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' END,
    remarks_cn = CASE WHEN remarks_cn IS NULL OR remarks_cn = '' THEN '一般行业知识，非Tassure内部资料核实：此流程说明是新加坡公司法/ACRA的一般监管要求，并非来自Tassure提供的文件——实际执行前请与Tassure秘书团队确认具体操作步骤。' ELSE remarks_cn || ' ' || '一般行业知识，非Tassure内部资料核实：此流程说明是新加坡公司法/ACRA的一般监管要求，并非来自Tassure提供的文件——实际执行前请与Tassure秘书团队确认具体操作步骤。' END
WHERE item_code = 'PC1-a'
  AND (remarks_en IS NULL OR remarks_en NOT LIKE '%GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED%');

UPDATE public.service_pricing
SET description_en = COALESCE(description_en, '') || E'\n\n' || 'General process: pass a board resolution approving the new registered address, then lodge the Notice of Change of Registered Office Address with ACRA via BizFile+, typically within 14 days of the change. The company must be reachable at its registered address at all times during business hours.',
    description_cn = COALESCE(description_cn, '') || E'\n\n' || '一般流程：董事会通过决议批准新的注册地址，随后通过BizFile+向ACRA提交注册地址变更通知，一般须在变更后14天内完成。公司在营业时间内必须能在注册地址被联系到。',
    remarks_en = CASE WHEN remarks_en IS NULL OR remarks_en = '' THEN 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' ELSE remarks_en || ' ' || 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' END,
    remarks_cn = CASE WHEN remarks_cn IS NULL OR remarks_cn = '' THEN '一般行业知识，非Tassure内部资料核实：此流程说明是新加坡公司法/ACRA的一般监管要求，并非来自Tassure提供的文件——实际执行前请与Tassure秘书团队确认具体操作步骤。' ELSE remarks_cn || ' ' || '一般行业知识，非Tassure内部资料核实：此流程说明是新加坡公司法/ACRA的一般监管要求，并非来自Tassure提供的文件——实际执行前请与Tassure秘书团队确认具体操作步骤。' END
WHERE item_code = 'PC1-b'
  AND (remarks_en IS NULL OR remarks_en NOT LIKE '%GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED%');

UPDATE public.service_pricing
SET description_en = COALESCE(description_en, '') || E'\n\n' || 'General process: the outgoing secretary resigns (or is removed by board resolution) and the incoming secretary is appointed by board resolution, then both the resignation and new appointment are lodged with ACRA via BizFile+, typically within 14 days. A private company must always have at least one company secretary -- Singapore law does not allow the position to be vacant beyond 6 months from when it first falls vacant, and in practice a same-day handover (no gap) is standard secretarial practice.',
    description_cn = COALESCE(description_cn, '') || E'\n\n' || '一般流程：离任秘书辞任（或由董事会决议解任），新任秘书由董事会决议委任，随后将辞任及新任命通过BizFile+向ACRA申报，一般须在14天内完成。私人公司必须始终有至少一名公司秘书在任——法律规定该职位空缺不得超过6个月，实务上通常做无缝交接（不留空档）。',
    remarks_en = CASE WHEN remarks_en IS NULL OR remarks_en = '' THEN 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' ELSE remarks_en || ' ' || 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' END,
    remarks_cn = CASE WHEN remarks_cn IS NULL OR remarks_cn = '' THEN '一般行业知识，非Tassure内部资料核实：此流程说明是新加坡公司法/ACRA的一般监管要求，并非来自Tassure提供的文件——实际执行前请与Tassure秘书团队确认具体操作步骤。' ELSE remarks_cn || ' ' || '一般行业知识，非Tassure内部资料核实：此流程说明是新加坡公司法/ACRA的一般监管要求，并非来自Tassure提供的文件——实际执行前请与Tassure秘书团队确认具体操作步骤。' END
WHERE item_code = 'PC1-c'
  AND (remarks_en IS NULL OR remarks_en NOT LIKE '%GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED%');

UPDATE public.service_pricing
SET description_en = COALESCE(description_en, '') || E'\n\n' || 'General process: pass a board resolution to update the company''s principal/secondary business activity (SSIC) codes, then lodge the change with ACRA via BizFile+. If the new activity requires a specific industry licence, that licence must be obtained before commencing the newly-added activity.',
    description_cn = COALESCE(description_cn, '') || E'\n\n' || '一般流程：董事会通过决议更新公司的主营业务/其他业务（SSIC编码），随后通过BizFile+向ACRA申报变更。若新增业务需要特定行业许可证，须在开展该新业务前先取得相应牌照。',
    remarks_en = CASE WHEN remarks_en IS NULL OR remarks_en = '' THEN 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' ELSE remarks_en || ' ' || 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' END,
