  AND (remarks_en IS NULL OR remarks_en NOT LIKE '%GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED%');

UPDATE public.service_pricing
SET description_en = COALESCE(description_en, '') || E'\n\n' || 'General process is more procedurally involved than most officer changes: appointing a NEW auditor is a straightforward board/shareholder resolution, but REMOVING an existing auditor before the end of their term requires special notice procedures under the Companies Act (the outgoing auditor has a right to make representations to shareholders, and in some cases an EGM may be required) -- this is not purely administrative and Tassure''s own compliance/legal input should be sought for the removal step specifically, not just the appointment of the replacement.',
    description_cn = COALESCE(description_cn, '') || E'\n\n' || '一般流程比大多数管理人员变更更复杂：委任新审计师本身只需简单的董事会/股东决议，但在任期届满前解任现有审计师，须依《公司法》的特别通知程序办理（离任审计师有权向股东作出陈述，某些情况下可能需要召开EGM）——这不是纯行政程序，"解任"这一步建议单独征询Tassure的合规/法律意见，而不只是走新审计师委任的流程。',
    remarks_en = CASE WHEN remarks_en IS NULL OR remarks_en = '' THEN 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' ELSE remarks_en || ' ' || 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' END,
    remarks_cn = CASE WHEN remarks_cn IS NULL OR remarks_cn = '' THEN '一般行业知识，非Tassure内部资料核实：此流程说明是新加坡公司法/ACRA的一般监管要求，并非来自Tassure提供的文件——实际执行前请与Tassure秘书团队确认具体操作步骤。' ELSE remarks_cn || ' ' || '一般行业知识，非Tassure内部资料核实：此流程说明是新加坡公司法/ACRA的一般监管要求，并非来自Tassure提供的文件——实际执行前请与Tassure秘书团队确认具体操作步骤。' END
WHERE item_code = 'PC1-e'
  AND (remarks_en IS NULL OR remarks_en NOT LIKE '%GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED%');

UPDATE public.service_pricing
SET description_en = COALESCE(description_en, '') || E'\n\n' || 'General process: appointment is by board resolution (for a director) or shareholder/board resolution as applicable, resignation is by the officer''s own written notice or removal resolution— either way, lodge the change with ACRA via BizFile+, typically within 14 days. A private company must have at least 1 resident director at all times -- a resignation cannot be lodged if it would leave the company with zero resident directors.',
    description_cn = COALESCE(description_cn, '') || E'\n\n' || '一般流程：委任由董事会决议（针对董事）或相应的股东/董事会决议完成，辞任由该管理人员书面通知或解任决议完成；无论哪种情况，都须通过BizFile+向ACRA申报，一般须在14天内完成。私人公司必须始终至少有1名本地居民董事——如果某次辞任会导致公司零本地董事，该辞任申报无法完成。',
    remarks_en = CASE WHEN remarks_en IS NULL OR remarks_en = '' THEN 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' ELSE remarks_en || ' ' || 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' END,
    remarks_cn = CASE WHEN remarks_cn IS NULL OR remarks_cn = '' THEN '一般行业知识，非Tassure内部资料核实：此流程说明是新加坡公司法/ACRA的一般监管要求，并非来自Tassure提供的文件——实际执行前请与Tassure秘书团队确认具体操作步骤。' ELSE remarks_cn || ' ' || '一般行业知识，非Tassure内部资料核实：此流程说明是新加坡公司法/ACRA的一般监管要求，并非来自Tassure提供的文件——实际执行前请与Tassure秘书团队确认具体操作步骤。' END
WHERE item_code = 'PC1-g'
  AND (remarks_en IS NULL OR remarks_en NOT LIKE '%GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED%');

UPDATE public.service_pricing
SET description_en = COALESCE(description_en, '') || E'\n\n' || 'General process: an INTERIM dividend is declared by board resolution— a FINAL dividend is declared by shareholder resolution (typically at the AGM). Either way, the company may only declare a dividend out of profits actually available for distribution -- the directors must be satisfied the company will remain solvent after payment. No direct ACRA lodgment is required for the dividend itself, though it is reflected in the company''s financial statements.',
    description_cn = COALESCE(description_cn, '') || E'\n\n' || '一般流程：中期股息由董事会决议宣布；末期股息由股东决议宣布（通常在年度股东大会上）。无论哪种情况，公司只能以实际可分配的利润宣布股息——董事须确认派息后公司仍具偿债能力。股息本身一般无需直接向ACRA申报，但会反映在公司财务报表中。',
    remarks_en = CASE WHEN remarks_en IS NULL OR remarks_en = '' THEN 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' ELSE remarks_en || ' ' || 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' END,
    remarks_cn = CASE WHEN remarks_cn IS NULL OR remarks_cn = '' THEN '一般行业知识，非Tassure内部资料核实：此流程说明是新加坡公司法/ACRA的一般监管要求，并非来自Tassure提供的文件——实际执行前请与Tassure秘书团队确认具体操作步骤。' ELSE remarks_cn || ' ' || '一般行业知识，非Tassure内部资料核实：此流程说明是新加坡公司法/ACRA的一般监管要求，并非来自Tassure提供的文件——实际执行前请与Tassure秘书团队确认具体操作步骤。' END
WHERE item_code = 'PC1-h'
  AND (remarks_en IS NULL OR remarks_en NOT LIKE '%GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED%');

UPDATE public.service_pricing
SET description_en = COALESCE(description_en, '') || E'\n\n' || 'General process: shareholders pass a special resolution (75% majority) approving the new name, Tassure checks the proposed name''s availability on ACRA''s system, then the name change is lodged with ACRA via BizFile+. If the name is available and there is no objection, ACRA typically approves within 1-2 working days and issues a new electronic Certificate of Incorporation (Change of Name) -- all other registration numbers (UEN, etc.) stay the same, only the name changes.',
    description_cn = COALESCE(description_cn, '') || E'\n\n' || '一般流程：股东通过特别决议（75%多数）批准新公司名称，Tassure在ACRA系统上核实新名称是否可用，随后通过BizFile+向ACRA申报名称变更。若名称可用且无异议，ACRA一般在1-2个工作日内批准，并签发新的电子版公司注册证书（名称变更版）——其他注册信息（如UEN）保持不变，只有名称改变。',
    remarks_en = CASE WHEN remarks_en IS NULL OR remarks_en = '' THEN 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' ELSE remarks_en || ' ' || 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' END,
    remarks_cn = CASE WHEN remarks_cn IS NULL OR remarks_cn = '' THEN '一般行业知识，非Tassure内部资料核实：此流程说明是新加坡公司法/ACRA的一般监管要求，并非来自Tassure提供的文件——实际执行前请与Tassure秘书团队确认具体操作步骤。' ELSE remarks_cn || ' ' || '一般行业知识，非Tassure内部资料核实：此流程说明是新加坡公司法/ACRA的一般监管要求，并非来自Tassure提供的文件——实际执行前请与Tassure秘书团队确认具体操作步骤。' END
WHERE item_code = 'PC2-a'
  AND (remarks_en IS NULL OR remarks_en NOT LIKE '%GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED%');

UPDATE public.service_pricing
SET description_en = COALESCE(description_en, '') || E'\n\n' || 'General process: shareholders pass a special resolution (75% majority) approving the amendment, then the amended constitution is lodged with ACRA via BizFile+. Simple amendments (e.g. updating the registered office clause) are usually straightforward— amendments affecting share classes, rights, or more complex structural matters typically need legal review before the resolution is put to shareholders.',
    description_cn = COALESCE(description_cn, '') || E'\n\n' || '一般流程：股东通过特别决议（75%多数）批准章程修改，随后将修订后的章程通过BizFile+向ACRA申报。简单的修改（如更新注册地址条款）一般较为直接；涉及股份类别、权利或更复杂结构性事项的修改，通常需要在提交股东表决前先经过法律审阅。',
    remarks_en = CASE WHEN remarks_en IS NULL OR remarks_en = '' THEN 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' ELSE remarks_en || ' ' || 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' END,
    remarks_cn = CASE WHEN remarks_cn IS NULL OR remarks_cn = '' THEN '一般行业知识，非Tassure内部资料核实：此流程说明是新加坡公司法/ACRA的一般监管要求，并非来自Tassure提供的文件——实际执行前请与Tassure秘书团队确认具体操作步骤。' ELSE remarks_cn || ' ' || '一般行业知识，非Tassure内部资料核实：此流程说明是新加坡公司法/ACRA的一般监管要求，并非来自Tassure提供的文件——实际执行前请与Tassure秘书团队确认具体操作步骤。' END
WHERE item_code = 'PC2-b'
  AND (remarks_en IS NULL OR remarks_en NOT LIKE '%GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED%');

UPDATE public.service_pricing
SET description_en = COALESCE(description_en, '') || E'\n\n' || 'General process: a board resolution authorises the split or replacement (e.g. a lost/damaged original certificate), the company secretary updates the register of members accordingly, and a new share certificate is issued to the shareholder. This is primarily an internal company administrative act -- it does not itself require a fresh ACRA lodgment unless the underlying shareholding also changes.',
    description_cn = COALESCE(description_cn, '') || E'\n\n' || '一般流程：董事会决议授权分割或补发（如原证书遗失/损毁），公司秘书相应更新股东名册，并向股东签发新的股份证书。这主要是公司内部行政事项——除非底层持股本身也发生变化，否则本身不需要另外向ACRA申报。',
    remarks_en = CASE WHEN remarks_en IS NULL OR remarks_en = '' THEN 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' ELSE remarks_en || ' ' || 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' END,
    remarks_cn = CASE WHEN remarks_cn IS NULL OR remarks_cn = '' THEN '一般行业知识，非Tassure内部资料核实：此流程说明是新加坡公司法/ACRA的一般监管要求，并非来自Tassure提供的文件——实际执行前请与Tassure秘书团队确认具体操作步骤。' ELSE remarks_cn || ' ' || '一般行业知识，非Tassure内部资料核实：此流程说明是新加坡公司法/ACRA的一般监管要求，并非来自Tassure提供的文件——实际执行前请与Tassure秘书团队确认具体操作步骤。' END
WHERE item_code = 'PC2-c'
  AND (remarks_en IS NULL OR remarks_en NOT LIKE '%GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED%');

UPDATE public.service_pricing
SET description_en = COALESCE(description_en, '') || E'\n\n' || 'General process: once a secured loan/debenture that created the registered charge has been fully repaid, the chargee (usually the bank) provides a satisfaction/discharge document, which is then lodged with ACRA to remove ("satisfy") the charge from the public Register of Charges -- this clears the charge from any future company search.',
    description_cn = COALESCE(description_cn, '') || E'\n\n' || '一般流程：一旦当初设立抵押/贷款登记的担保贷款已全部还清，抵押权人（通常为银行）会出具解除/清偿文件，随后向ACRA申报以从公开的贷款登记册中"注销"该抵押——此后任何公司查册都不会再显示该笔抵押。',
    remarks_en = CASE WHEN remarks_en IS NULL OR remarks_en = '' THEN 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' ELSE remarks_en || ' ' || 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' END,
