  AND (remarks_en IS NULL OR remarks_en NOT LIKE '%GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED%');

UPDATE public.service_pricing
SET description_en = COALESCE(description_en, '') || E'\n\n' || 'Same general process as an ordinary Share Transfer, with one addition: when the transferor or transferee is itself a corporate entity, that entity''s own board resolution (or equivalent internal authorisation) approving the transfer, plus its own KYC/corporate documents, are typically required alongside the usual instrument of transfer and stamp duty.',
    description_cn = COALESCE(description_cn, '') || E'\n\n' || '与普通股份转让的一般流程相同，另需注意：若转让方或受让方本身为法人实体，通常还需要该法人实体自身的董事会决议（或同等内部授权文件）批准该转让，以及该法人实体自身的KYC/公司文件，与常规的转让文书及印花税一并提交。',
    remarks_en = CASE WHEN remarks_en IS NULL OR remarks_en = '' THEN 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' ELSE remarks_en || ' ' || 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' END,
