UPDATE public.service_pricing
SET description_en = COALESCE(description_en, '') || E'\n\n' || 'General scope: this is a PERIODIC/ONGOING re-verification of an existing client''s KYC information (as opposed to the one-time checklist done at incorporation, see the Company Incorporation Service row) -- confirming director/shareholder identity and address are still current, screening for adverse media/sanctions, and refreshing the risk assessment. Regulated corporate service providers are expected to periodically re-verify existing clients, not just screen new ones.',
    description_cn = COALESCE(description_cn, '') || E'\n\n' || '一般范围：这是对现有客户KYC信息的定期/持续重新核实（区别于公司设立时做的一次性清单，详见"公司注册服务"一行）——确认董事/股东身份及地址信息仍然有效、进行负面新闻/制裁名单筛查，并更新风险评估。受监管的企业服务提供商通常须对现有客户进行定期重新核实，而不只是在新客户入职时做一次。',
    remarks_en = CASE WHEN remarks_en IS NULL OR remarks_en = '' THEN 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' ELSE remarks_en || ' ' || 'GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED: this process description is standard Singapore Companies Act / ACRA regulatory practice, not sourced from a Tassure document -- confirm Tassure''s own specific execution steps before relying on this to actually perform the task.' END,
    remarks_cn = CASE WHEN remarks_cn IS NULL OR remarks_cn = '' THEN '一般行业知识，非Tassure内部资料核实：此流程说明是新加坡公司法/ACRA的一般监管要求，并非来自Tassure提供的文件——实际执行前请与Tassure秘书团队确认具体操作步骤。' ELSE remarks_cn || ' ' || '一般行业知识，非Tassure内部资料核实：此流程说明是新加坡公司法/ACRA的一般监管要求，并非来自Tassure提供的文件——实际执行前请与Tassure秘书团队确认具体操作步骤。' END
WHERE item_code = 'PC9-d'
  AND (remarks_en IS NULL OR remarks_en NOT LIKE '%GENERAL KNOWLEDGE, NOT TASSURE-VERIFIED%');

